export const code = async (inputs) => {
  const b = (v) => v === true || v === 'true';
  // Две причины молчания, и их надо различать в логе прогона:
  // ключ уже занят (послесловие ушло раньше) против «не приходил».
  const reason = !b(inputs.acquired) ? 'already_sent' : (!b(inputs.attended) ? 'not_attended' : 'unknown');
  return { skipped: true, reason: reason, now: new Date().toISOString() };
};

export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] || key);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  // Эталон экранирования MarkdownV2 — catalog/snippets/markdown-v2.md.
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');

  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };

  const str = (v) => String(v === undefined || v === null ? '' : v);
  const acquired = inputs.acquired === true || inputs.acquired === 'true';
  const reg = arr(inputs.registration).map(flat)[0] || {};
  // «Не уходит тому, кто не приходил»: единственное доказательство присутствия —
  // проставленный checked_in_at, а не статус регистрации.
  const attended = str(reg.checked_in_at) !== '' && str(reg.checked_in_at) !== '-';

  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const parse = (iso) => {
    if (!iso) return NaN;
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    return Date.parse(s);
  };

  const thisEventId = str(inputs.eventId);
  const now = Date.now();
  const upcoming = arr(inputs.events).map(flat)
    .filter((e) => str(e.id) !== thisEventId)
    .filter((e) => str(e.cancelled_at) === '' && str(e.finished_at) === '')
    .map((e) => ({ e: e, ts: parse(e.starts_at) }))
    .filter((x) => isFinite(x.ts) && x.ts > now)
    .sort((a, b) => a.ts - b.ts);
  const next = upcoming.length ? upcoming[0] : null;

  const shouldSend = acquired && attended;

  const lines = [esc(t('afterword.thanks'))];
  const buttons = [];
  if (next) {
    lines.push(esc(t('afterword.next_header')));
    const card = ['*' + esc(str(next.e.title)) + '*', '📅 ' + esc(dateFmt.format(new Date(next.ts)))];
    if (str(next.e.address)) card.push('📍 ' + esc(str(next.e.address)));
    lines.push(card.join('\n'));
    buttons.push([{ text: t('afterword.btn_next'), url: 'https://t.me/' + str(inputs.botUsername) + '?start=e' + str(next.e.id) + '-afterword' }]);
  } else {
    lines.push(esc(t('afterword.no_next')));
  }

  return {
    shouldSend: shouldSend,
    acquired: acquired,
    attended: attended,
    hasNext: !!next,
    nextEventId: next ? str(next.e.id) : '',
    text: lines.join('\n\n'),
    replyMarkup: buttons.length ? { inline_keyboard: buttons } : null,
    now: new Date().toISOString()
  };
};
